('c1', 'Beginner Starter', 'Your first 30 days of English, one week at a time.', 'Pre-A1', 'published', 1)
insert into public.lessons (id, course_id, title_en, level, sequence_number, week, learning_objectives, prerequisite_lesson_ids, estimated_duration_seconds, completion_min_score, is_assessment, content_json, content_version, published_status) values
('l1', 'c1', 'Greetings and polite words', 'Pre-A1', 1, 'w1', array['Say hello and goodbye','Ask and answer How are you?','Use please and thank you']::text[], array[]::text[], 600, 0.6, false, $j$[{"position":0,"exercise_id":"l1-0"},{"position":1,"stage":"listen","type":"listen","audio_en":"Hello! How are you?","meaning_bn":"হ্যালো! আপনি কেমন আছেন?"},{"position":2,"stage":"learn","type":"teach","grammar_en":"Greeting and replying","pattern_en":"How are you? / I am fine, thank you.","examples_en":["Hello.","How are you?","I am fine, thank you.","Goodbye."],"vocabulary":[{"en":"Hello","bn":"হ্যালো, নমস্কার"},{"en":"Goodbye","bn":"বিদায়"},{"en":"Please","bn":"অনুগ্রহ করে"},{"en":"Thank you","bn":"ধন্যবাদ"}],"explanation_bn":"দেখা হলে Hello বলুন। কেমন আছেন জানতে How are you? বলুন। উত্তরে বলুন I am fine, thank you."},{"position":3,"stage":"speak","type":"repeat","text_en":"How are you?"},{"position":4,"exercise_id":"l1-4"},{"position":5,"exercise_id":"l1-5"},{"position":6,"exercise_id":"l1-6"},{"position":7,"exercise_id":"l1-7"},{"position":8,"stage":"review","type":"review"}]$j$::jsonb, 1, 'published'),
('l2', 'c1', 'Names and introductions', 'Pre-A1', 2, 'w1', array['Say your name','Ask someone their name','Say Nice to meet you']::text[], array['l1']::text[], 600, 0.6, false, $j$[{"position":0,"exercise_id":"l2-0"},{"position":1,"stage":"listen","type":"listen","audio_en":"Hello. My name is Rahim.","meaning_bn":"হ্যালো। আমার নাম রহিম।"},{"position":2,"stage":"learn","type":"teach","grammar_en":"Telling your name","pattern_en":"My name is + name / I am + name","examples_en":["My name is Rahim.","I am Rahim.","What is your name?","Nice to meet you."],"vocabulary":[{"en":"name","bn":"নাম"},{"en":"my","bn":"আমার"},{"en":"your","bn":"আপনার"}],"explanation_bn":"নিজের নাম বলতে 'My name is' বা 'I am' ব্যবহার করুন। অন্যের নাম জানতে 'What is your name?' জিজ্ঞেস করুন।"},{"position":3,"stage":"speak","type":"repeat","text_en":"My name is Rahim."},{"position":4,"exercise_id":"l2-4"},{"position":5,"exercise_id":"l2-5"},{"position":6,"exercise_id":"l2-6"},{"position":7,"exercise_id":"l2-7"},{"position":8,"stage":"review","type":"review"}]$j$::jsonb, 1, 'published'),
('l4', 'c1', 'Pronouns with am, is, are', 'Pre-A1', 3, 'w1', array['Use I, you, he, she, we, they','Choose am, is or are']::text[], array['l2']::text[], 600, 0.6, false, $j$[{"position":0,"exercise_id":"l4-0"},{"position":1,"stage":"listen","type":"listen","audio_en":"I am a student. She is a teacher.","meaning_bn":"আমি একজন ছাত্র। সে একজন শিক্ষক।"},{"position":2,"stage":"learn","type":"teach","grammar_en":"Pronouns with am, is, are","pattern_en":"I am / you are / he is / she is / we are / they are","examples_en":["I am a student.","You are a teacher.","He is my friend.","She is at home.","We are happy.","They are in Dhaka."],"vocabulary":[{"en":"I","bn":"আমি"},{"en":"you","bn":"তুমি, আপনি"},{"en":"he","bn":"সে (পুরুষ)"},{"en":"she","bn":"সে (নারী)"},{"en":"we","bn":"আমরা"},{"en":"they","bn":"তারা"}],"explanation_bn":"I-এর সঙ্গে am, he/she-এর সঙ্গে is, আর you/we/they-এর সঙ্গে are বসে।"},{"position":3,"stage":"speak","type":"repeat","text_en":"She is a teacher."},{"position":4,"exercise_id":"l4-4"},{"position":5,"exercise_id":"l4-5"},{"position":6,"exercise_id":"l4-6"},{"position":7,"exercise_id":"l4-7"},{"position":8,"stage":"review","type":"review"}]$j$::jsonb, 1, 'published'),
('l5', 'c1', 'Yes/no questions', 'Pre-A1', 4, 'w1', array['Ask yes/no questions with am, is, are','Give short answers']::text[], array['l4']::text[], 600, 0.6, false, $j$[{"position":0,"exercise_id":"l5-0"},{"position":1,"stage":"listen","type":"listen","audio_en":"Are you a student? Yes, I am.","meaning_bn":"আপনি কি ছাত্র? হ্যাঁ, আমি ছাত্র।"},{"position":2,"stage":"learn","type":"teach","grammar_en":"Yes/no questions with am, is, are","pattern_en":"Are you ...? Yes, I am. / No, I am not.","examples_en":["Are you a student?","Yes, I am.","No, I am not.","Is she a teacher?","Yes, she is."],"vocabulary":[{"en":"yes","bn":"হ্যাঁ"},{"en":"no","bn":"না"},{"en":"not","bn":"না (নেতিবাচক)"}],"explanation_bn":"প্রশ্নে am/is/are বাক্যের শুরুতে আসে। উত্তরে Yes বা No বলে ছোট উত্তর দিন।"},{"position":3,"stage":"speak","type":"repeat","text_en":"Are you a student?"},{"position":4,"exercise_id":"l5-4"},{"position":5,"exercise_id":"l5-5"},{"position":6,"exercise_id":"l5-6"},{"position":7,"exercise_id":"l5-7"},{"position":8,"stage":"review","type":"review"}]$j$::jsonb, 1, 'published'),
('l6', 'c1', 'Simple personal information', 'Pre-A1', 5, 'w1', array['Say where you are from','Say your age and job']::text[], array['l5']::text[], 600, 0.6, false, $j$[{"position":0,"exercise_id":"l6-0"},{"position":1,"stage":"listen","type":"listen","audio_en":"I am from Bangladesh. I am twenty years old.","meaning_bn":"আমি বাংলাদেশ থেকে এসেছি। আমার বয়স কুড়ি বছর।"},{"position":2,"stage":"learn","type":"teach","grammar_en":"Talking about yourself","pattern_en":"I am from + place. / I am + number + years old.","examples_en":["I am from Bangladesh.","I am twenty years old.","I am a student.","I am from Dhaka."],"vocabulary":[{"en":"from","bn":"থেকে"},{"en":"years old","bn":"বছর বয়স"},{"en":"student","bn":"ছাত্র"},{"en":"teacher","bn":"শিক্ষক"}],"explanation_bn":"নিজের দেশ বা শহর বলতে 'I am from', বয়স বলতে 'I am ... years old' ব্যবহার করুন।"},{"position":3,"stage":"speak","type":"repeat","text_en":"I am from Bangladesh."},{"position":4,"exercise_id":"l6-4"},{"position":5,"exercise_id":"l6-5"},{"position":6,"exercise_id":"l6-6"},{"position":7,"exercise_id":"l6-7"},{"position":8,"stage":"review","type":"review"}]$j$::jsonb, 1, 'published'),
('l7', 'c1', 'Numbers, days and classroom words', 'Pre-A1', 6, 'w1', array['Count from one to ten','Say the days','Understand classroom instructions']::text[], array['l6']::text[], 600, 0.6, false, $j$[{"position":0,"exercise_id":"l7-0"},{"position":1,"stage":"listen","type":"listen","audio_en":"Open your book. Listen and repeat.","meaning_bn":"আপনার বই খুলুন। শুনুন এবং বলুন।"},{"position":2,"stage":"learn","type":"teach","grammar_en":"Numbers, days and classroom instructions","pattern_en":"one, two, three ... ten / Monday ... Sunday","examples_en":["One, two, three.","Today is Friday.","Open your book.","Listen and repeat."],"vocabulary":[{"en":"one","bn":"এক"},{"en":"two","bn":"দুই"},{"en":"three","bn":"তিন"},{"en":"ten","bn":"দশ"},{"en":"Monday","bn":"সোমবার"},{"en":"Friday","bn":"শুক্রবার"},{"en":"Sunday","bn":"রবিবার"}],"explanation_bn":"এক থেকে দশ গুনতে শিখুন। দিনের নাম বড় হাতের অক্ষরে শুরু হয়। ক্লাসে শুনবেন Open your book, Listen, Repeat।"},{"position":3,"stage":"speak","type":"repeat","text_en":"Open your book."},{"position":4,"exercise_id":"l7-4"},{"position":5,"exercise_id":"l7-5"},{"position":6,"exercise_id":"l7-6"},{"position":7,"exercise_id":"l7-7"},{"position":8,"stage":"review","type":"review"}]$j$::jsonb, 1, 'published'),
('l8', 'c1', 'Listening: short greetings', 'Pre-A1', 7, 'w1', array['Understand greetings through the day','Reply to a short greeting']::text[], array['l7']::text[], 600, 0.6, false, $j$[{"position":0,"exercise_id":"l8-0"},{"position":1,"stage":"listen","type":"listen","audio_en":"Good morning. How are you today?","meaning_bn":"শুভ সকাল। আজ আপনি কেমন আছেন?"},{"position":2,"stage":"learn","type":"teach","grammar_en":"Greetings through the day","pattern_en":"Good morning / Good afternoon / Good evening / Good night","examples_en":["Good morning.","Good afternoon.","Good evening.","Good night.","See you tomorrow."],"vocabulary":[{"en":"morning","bn":"সকাল"},{"en":"afternoon","bn":"দুপুর, বিকেল"},{"en":"evening","bn":"সন্ধ্যা"},{"en":"night","bn":"রাত"}],"explanation_bn":"দিনের সময় অনুযায়ী শুভেচ্ছা বদলায়। রাতে বিদায়ের সময় Good night বলা হয়।"},{"position":3,"stage":"speak","type":"repeat","text_en":"Good morning."},{"position":4,"exercise_id":"l8-4"},{"position":5,"exercise_id":"l8-5"},{"position":6,"exercise_id":"l8-6"},{"position":7,"exercise_id":"l8-7"},{"position":8,"stage":"review","type":"review"}]$j$::jsonb, 1, 'published'),
('l9', 'c1', 'Common verbs and present simple', 'A1', 8, 'w2', array['Use common verbs','Add s for he and she']::text[], array['l8']::text[], 600, 0.6, false, $j$[{"position":0,"exercise_id":"l9-0"},{"position":1,"stage":"listen","type":"listen","audio_en":"I eat rice. She eats fish.","meaning_bn":"আমি ভাত খাই। সে মাছ খায়।"},{"position":2,"stage":"learn","type":"teach","grammar_en":"Present simple with common verbs","pattern_en":"I / you / we / they + verb. He / she + verb + s","examples_en":["I eat rice.","You go to school.","She eats fish.","He reads a book.","They play football."],"vocabulary":[{"en":"eat","bn":"খাওয়া"},{"en":"go","bn":"যাওয়া"},{"en":"read","bn":"পড়া"},{"en":"play","bn":"খেলা"}],"explanation_bn":"অভ্যাস বা সাধারণ সত্য বলতে present simple ব্যবহার হয়। he/she-এর সঙ্গে ক্রিয়ার শেষে s বসে।"},{"position":3,"stage":"speak","type":"repeat","text_en":"She eats fish."},{"position":4,"exercise_id":"l9-4"},{"position":5,"exercise_id":"l9-5"},{"position":6,"exercise_id":"l9-6"},{"position":7,"exercise_id":"l9-7"},{"position":8,"stage":"review","type":"review"}]$j$::jsonb, 1, 'published'),
('l10', 'c1', 'Daily routines', 'A1', 9, 'w2', array['Talk about your day','Say the time with at']::text[], array['l9']::text[], 600, 0.6, false, $j$[{"position":0,"exercise_id":"l10-0"},{"position":1,"stage":"listen","type":"listen","audio_en":"I wake up at six. I go to work.","meaning_bn":"আমি ছয়টায় ঘুম থেকে উঠি। আমি কাজে যাই।"},{"position":2,"stage":"learn","type":"teach","grammar_en":"Talking about your day","pattern_en":"I + verb + at + time","examples_en":["I wake up at six.","I eat breakfast at seven.","I go to school at eight.","I sleep at ten."],"vocabulary":[{"en":"wake up","bn":"ঘুম থেকে ওঠা"},{"en":"breakfast","bn":"সকালের নাস্তা"},{"en":"sleep","bn":"ঘুমানো"},{"en":"work","bn":"কাজ"}],"explanation_bn":"সময় বলতে 'at' ব্যবহার করুন, যেমন at six।"},{"position":3,"stage":"speak","type":"repeat","text_en":"I wake up at six."},{"position":4,"exercise_id":"l10-4"},{"position":5,"exercise_id":"l10-5"},{"position":6,"exercise_id":"l10-6"},{"position":7,"exercise_id":"l10-7"},{"position":8,"stage":"review","type":"review"}]$j$::jsonb, 1, 'published'),
('l11', 'c1', 'Likes and dislikes', 'A1', 10, 'w2', array['Say what you like','Say what you do not like']::text[], array['l10']::text[], 600, 0.6, false, $j$[{"position":0,"exercise_id":"l11-0"},{"position":1,"stage":"listen","type":"listen","audio_en":"I like tea. I do not like coffee.","meaning_bn":"আমি চা পছন্দ করি। আমি কফি পছন্দ করি না।"},{"position":2,"stage":"learn","type":"teach","grammar_en":"Likes and dislikes","pattern_en":"I like + noun. / I do not like + noun.","examples_en":["I like tea.","I do not like coffee.","She likes fish.","He does not like milk."],"vocabulary":[{"en":"like","bn":"পছন্দ করা"},{"en":"tea","bn":"চা"},{"en":"coffee","bn":"কফি"},{"en":"fish","bn":"মাছ"}],"explanation_bn":"পছন্দ বোঝাতে like, অপছন্দ বোঝাতে do not like। he/she-এর সঙ্গে likes ও does not like।"},{"position":3,"stage":"speak","type":"repeat","text_en":"I like tea."},{"position":4,"exercise_id":"l11-4"},{"position":5,"exercise_id":"l11-5"},{"position":6,"exercise_id":"l11-6"},{"position":7,"exercise_id":"l11-7"},{"position":8,"stage":"review","type":"review"}]$j$::jsonb, 1, 'published'),
('l3', 'c1', 'Say what you want to do', 'A1', 11, 'w2', array['Use I want to + verb','Make your own sentence']::text[], array['l11']::text[], 600, 0.6, false, $j$[{"position":0,"exercise_id":"l3-0"},{"position":1,"stage":"listen","type":"listen","audio_en":"I want to learn English.","meaning_bn":"আমি ইংরেজি শিখতে চাই।"},{"position":2,"stage":"learn","type":"teach","grammar_en":"Saying what you want to do","pattern_en":"I want to + verb","examples_en":["I want to learn English.","I want to speak English.","I want to eat rice."],"vocabulary":[{"en":"learn","bn":"শেখা"},{"en":"speak","bn":"বলা"},{"en":"eat","bn":"খাওয়া"}],"explanation_bn":"কী করতে চান বলতে 'I want to' এর পরে একটি ক্রিয়া বসান।"},{"position":3,"stage":"speak","type":"repeat","text_en":"I want to learn English."},{"position":4,"exercise_id":"l3-4"},{"position":5,"exercise_id":"l3-5"},{"position":6,"exercise_id":"l3-6"},{"position":7,"exercise_id":"l3-7"},{"position":8,"stage":"review","type":"review"}]$j$::jsonb, 1, 'published'),
('l12', 'c1', 'Question words', 'A1', 12, 'w2', array['Ask with What, Where, Who, When, Why, How']::text[], array['l3']::text[], 600, 0.6, false, $j$[{"position":0,"exercise_id":"l12-0"},{"position":1,"stage":"listen","type":"listen","audio_en":"What is your name? Where do you live?","meaning_bn":"আপনার নাম কী? আপনি কোথায় থাকেন?"},{"position":2,"stage":"learn","type":"teach","grammar_en":"Basic question words","pattern_en":"What / Where / Who / When / Why / How + question","examples_en":["What is your name?","Where do you live?","Who is he?","When do you eat?","How are you?"],"vocabulary":[{"en":"what","bn":"কী"},{"en":"where","bn":"কোথায়"},{"en":"who","bn":"কে"},{"en":"when","bn":"কখন"},{"en":"why","bn":"কেন"},{"en":"how","bn":"কেমন, কীভাবে"}],"explanation_bn":"প্রশ্ন শুরু করতে What, Where, Who, When, Why, How ব্যবহার করুন।"},{"position":3,"stage":"speak","type":"repeat","text_en":"Where do you live?"},{"position":4,"exercise_id":"l12-4"},{"position":5,"exercise_id":"l12-5"},{"position":6,"exercise_id":"l12-6"},{"position":7,"exercise_id":"l12-7"},{"position":8,"stage":"review","type":"review"}]$j$::jsonb, 1, 'published'),
('l13', 'c1', 'Time and frequency', 'A1', 13, 'w2', array['Say how often you do things','Say the time with o''clock']::text[], array['l12']::text[], 600, 0.6, false, $j$[{"position":0,"exercise_id":"l13-0"},{"position":1,"stage":"listen","type":"listen","audio_en":"I always drink tea. I never drink coffee.","meaning_bn":"আমি সবসময় চা খাই। আমি কখনো কফি খাই না।"},{"position":2,"stage":"learn","type":"teach","grammar_en":"How often?","pattern_en":"always / usually / sometimes / never + verb","examples_en":["I always drink tea.","I usually go at eight.","I sometimes read a book.","I never eat fish.","It is six o'clock."],"vocabulary":[{"en":"always","bn":"সবসময়"},{"en":"usually","bn":"সাধারণত"},{"en":"sometimes","bn":"মাঝে মাঝে"},{"en":"never","bn":"কখনো না"},{"en":"o'clock","bn":"ঘড়িতে ... টা"}],"explanation_bn":"কত ঘন ঘন কিছু করেন বোঝাতে always, usually, sometimes, never ক্রিয়ার আগে বসে।"},{"position":3,"stage":"speak","type":"repeat","text_en":"I usually go at eight."},{"position":4,"exercise_id":"l13-4"},{"position":5,"exercise_id":"l13-5"},{"position":6,"exercise_id":"l13-6"},{"position":7,"exercise_id":"l13-7"},{"position":8,"stage":"review","type":"review"}]$j$::jsonb, 1, 'published'),
('l14', 'c1', 'Short answers', 'A1', 14, 'w2', array['Answer with Yes, I do / No, I do not','Use does for he and she']::text[], array['l13']::text[], 600, 0.6, false, $j$[{"position":0,"exercise_id":"l14-0"},{"position":1,"stage":"listen","type":"listen","audio_en":"Do you like tea? Yes, I do.","meaning_bn":"আপনি কি চা পছন্দ করেন? হ্যাঁ, করি।"},{"position":2,"stage":"learn","type":"teach","grammar_en":"Short answers with do and does","pattern_en":"Do you ...? Yes, I do. / No, I do not.","examples_en":["Do you like tea? Yes, I do.","Do you eat fish? No, I do not.","Does she read? Yes, she does.","Does he go? No, he does not."],"vocabulary":[{"en":"do","bn":"করা (প্রশ্নে)"},{"en":"does","bn":"করে (he/she-এর সঙ্গে)"}],"explanation_bn":"Do/Does দিয়ে প্রশ্ন করলে উত্তরে Yes, I do বা No, I do not বলুন। he/she হলে does ব্যবহার করুন।"},{"position":3,"stage":"speak","type":"repeat","text_en":"Yes, I do."},{"position":4,"exercise_id":"l14-4"},{"position":5,"exercise_id":"l14-5"},{"position":6,"exercise_id":"l14-6"},{"position":7,"exercise_id":"l14-7"},{"position":8,"stage":"review","type":"review"}]$j$::jsonb, 1, 'published'),
('l15', 'c1', 'Listening: routine dialogues', 'A1', 15, 'w2', array['Follow a short routine dialogue','Find the time and the answer']::text[], array['l14']::text[], 600, 0.6, false, $j$[{"position":0,"exercise_id":"l15-0"},{"position":1,"stage":"listen","type":"listen","audio_en":"Do you wake up early? Yes, I always wake up at six.","meaning_bn":"আপনি কি ভোরে ওঠেন? হ্যাঁ, আমি সবসময় ছয়টায় উঠি।"},{"position":2,"stage":"learn","type":"teach","grammar_en":"Understanding routine dialogues","pattern_en":"Question + short answer + detail","examples_en":["Do you wake up early? Yes, I do.","What time do you eat? At seven.","Do you go to school? No, I do not."],"vocabulary":[{"en":"early","bn":"আগে, ভোরে"},{"en":"late","bn":"দেরিতে"},{"en":"every day","bn":"প্রতিদিন"}],"explanation_bn":"সংলাপ শুনলে আগে প্রশ্নটি ধরুন, তারপর উত্তরের সময় বা তথ্য খুঁজুন।"},{"position":3,"stage":"speak","type":"repeat","text_en":"What time do you eat?"},{"position":4,"exercise_id":"l15-4"},{"position":5,"exercise_id":"l15-5"},{"position":6,"exercise_id":"l15-6"},{"position":7,"exercise_id":"l15-7"},{"position":8,"stage":"review","type":"review"}]$j$::jsonb, 1, 'published'),
('l16', 'c1', 'Asking for help', 'A1', 16, 'w3', array['Get attention politely','Ask for help with Can you ...?']::text[], array['l15']::text[], 600, 0.6, false, $j$[{"position":0,"exercise_id":"l16-0"},{"position":1,"stage":"listen","type":"listen","audio_en":"Excuse me. Can you help me, please?","meaning_bn":"মাফ করবেন। আপনি কি আমাকে একটু সাহায্য করতে পারেন?"},{"position":2,"stage":"learn","type":"teach","grammar_en":"Asking for help politely","pattern_en":"Excuse me. Can you + verb + me, please?","examples_en":["Excuse me.","Can you help me, please?","Can you open the door, please?","Thank you for your help."],"vocabulary":[{"en":"excuse me","bn":"মাফ করবেন"},{"en":"help","bn":"সাহায্য"},{"en":"can","bn":"পারা"},{"en":"open","bn":"খোলা"}],"explanation_bn":"কাউকে ডাকতে Excuse me বলুন। সাহায্য চাইতে 'Can you ... please?' ব্যবহার করুন।"},{"position":3,"stage":"speak","type":"repeat","text_en":"Can you help me, please?"},{"position":4,"exercise_id":"l16-4"},{"position":5,"exercise_id":"l16-5"},{"position":6,"exercise_id":"l16-6"},{"position":7,"exercise_id":"l16-7"},{"position":8,"stage":"review","type":"review"}]$j$::jsonb, 1, 'published'),
